contracts/BlueReefRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title BlueReefRegistry
 * @dev Registry contract for managing blue carbon project applications
 */
contract BlueReefRegistry is AccessControl, ReentrancyGuard {
    using Counters for Counters.Counter;

    // Roles
    bytes32 public constant GOVERNMENT_ROLE = keccak256("GOVERNMENT_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    // Application status enum
    enum ApplicationStatus {
        Pending,
        UnderReview,
        Approved,
        Rejected,
        RequiresMoreInfo
    }

    // User type enum
    enum UserType {
        NGO,
        Panchayat,
        Government
    }

    // Application structure
    struct Application {
        uint256 id;
        address applicant;
        UserType userType;
        string organizationName;
        string documentHash; // IPFS hash of uploaded documents
        string landCoordinates; // JSON string of polygon coordinates
        uint256 areaHectares;
        string plantSpecies;
        ApplicationStatus status;
        uint256 submissionTimestamp;
        uint256 reviewTimestamp;
        address reviewer;
        string reviewComments;
        address projectContractAddress; // Set when approved
    }

    // State variables
    Counters.Counter private _applicationIds;
    mapping(uint256 => Application) public applications;
    mapping(address => uint256[]) public userApplications;
    mapping(address => bool) public registeredUsers;
    mapping(address => UserType) public userTypes;

    // Events
    event ApplicationSubmitted(
        uint256 indexed applicationId,
        address indexed applicant,
        UserType userType,
        string organizationName
    );

    event ApplicationStatusUpdated(
        uint256 indexed applicationId,
        ApplicationStatus oldStatus,
        ApplicationStatus newStatus,
        address indexed reviewer
    );

    event UserRegistered(
        address indexed user,
        UserType userType,
        string organizationName
    );

    event ProjectContractDeployed(
        uint256 indexed applicationId,
        address indexed projectContract
    );

    // Modifiers
    modifier onlyRegisteredUser() {
        require(registeredUsers[msg.sender], "User not registered");
        _;
    }

    modifier onlyGovernmentOrVerifier() {
        require(
            hasRole(GOVERNMENT_ROLE, msg.sender) || hasRole(VERIFIER_ROLE, msg.sender),
            "Caller is not government or verifier"
        );
        _;
    }

    modifier validApplicationId(uint256 _applicationId) {
        require(_applicationId > 0 && _applicationId <= _applicationIds.current(), "Invalid application ID");
        _;
    }

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(GOVERNMENT_ROLE, msg.sender);
    }

    /**
     * @dev Register a new user in the system
     * @param _userType Type of user (NGO, Panchayat, Government)
     * @param _organizationName Name of the organization
     */
    function registerUser(
        UserType _userType,
        string memory _organizationName
    ) external {
        require(!registeredUsers[msg.sender], "User already registered");
        require(bytes(_organizationName).length > 0, "Organization name required");

        registeredUsers[msg.sender] = true;
        userTypes[msg.sender] = _userType;

        emit UserRegistered(msg.sender, _userType, _organizationName);
    }

    /**
     * @dev Submit a new application for blue carbon project
     * @param _organizationName Name of the applying organization
     * @param _documentHash IPFS hash of uploaded documents
     * @param _landCoordinates JSON string of land polygon coordinates
     * @param _areaHectares Area of land in hectares
     * @param _plantSpecies Species of plants to be grown
     */
    function submitApplication(
        string memory _organizationName,
        string memory _documentHash,
        string memory _landCoordinates,
        uint256 _areaHectares,
        string memory _plantSpecies
    ) external onlyRegisteredUser nonReentrant {
        require(bytes(_organizationName).length > 0, "Organization name required");
        require(bytes(_documentHash).length > 0, "Document hash required");
        require(bytes(_landCoordinates).length > 0, "Land coordinates required");
        require(_areaHectares > 0, "Area must be greater than 0");
        require(bytes(_plantSpecies).length > 0, "Plant species required");

        _applicationIds.increment();
        uint256 newApplicationId = _applicationIds.current();

        Application storage newApplication = applications[newApplicationId];
        newApplication.id = newApplicationId;
        newApplication.applicant = msg.sender;
        newApplication.userType = userTypes[msg.sender];
        newApplication.organizationName = _organizationName;
        newApplication.documentHash = _documentHash;
        newApplication.landCoordinates = _landCoordinates;
        newApplication.areaHectares = _areaHectares;
        newApplication.plantSpecies = _plantSpecies;
        newApplication.status = ApplicationStatus.Pending;
        newApplication.submissionTimestamp = block.timestamp;

        userApplications[msg.sender].push(newApplicationId);

        emit ApplicationSubmitted(
            newApplicationId,
            msg.sender,
            userTypes[msg.sender],
            _organizationName
        );
    }

    /**
     * @dev Update application status (government/verifier only)
     * @param _applicationId ID of the application
     * @param _newStatus New status for the application
     * @param _comments Review comments
     */
    function updateApplicationStatus(
        uint256 _applicationId,
        ApplicationStatus _newStatus,
        string memory _comments
    ) external onlyGovernmentOrVerifier validApplicationId(_applicationId) {
        Application storage application = applications[_applicationId];
        ApplicationStatus oldStatus = application.status;

        require(oldStatus != _newStatus, "Status is already set to this value");
        require(oldStatus != ApplicationStatus.Approved, "Cannot modify approved application");

        application.status = _newStatus;
        application.reviewTimestamp = block.timestamp;
        application.reviewer = msg.sender;
        application.reviewComments = _comments;

        emit ApplicationStatusUpdated(_applicationId, oldStatus, _newStatus, msg.sender);
    }

    /**
     * @dev Set project contract address for approved application
     * @param _applicationId ID of the application
     * @param _projectContract Address of the deployed project contract
     */
    function setProjectContract(
        uint256 _applicationId,
        address _projectContract
    ) external onlyGovernmentOrVerifier validApplicationId(_applicationId) {
        require(_projectContract != address(0), "Invalid project contract address");
        
        Application storage application = applications[_applicationId];
        require(application.status == ApplicationStatus.Approved, "Application must be approved");
        require(application.projectContractAddress == address(0), "Project contract already set");

        application.projectContractAddress = _projectContract;

        emit ProjectContractDeployed(_applicationId, _projectContract);
    }

    /**
     * @dev Get application details
     * @param _applicationId ID of the application
     * @return Application struct
     */
    function getApplication(uint256 _applicationId) 
        external 
        view 
        validApplicationId(_applicationId) 
        returns (Application memory) 
    {
        return applications[_applicationId];
    }

    /**
     * @dev Get all applications by a user
     * @param _user Address of the user
     * @return Array of application IDs
     */
    function getUserApplications(address _user) external view returns (uint256[] memory) {
        return userApplications[_user];
    }

    /**
     * @dev Get applications by status
     * @param _status Status to filter by
     * @return Array of application IDs
     */
    function getApplicationsByStatus(ApplicationStatus _status) 
        external 
        view 
        returns (uint256[] memory) 
    {
        uint256 totalApplications = _applicationIds.current();
        uint256[] memory tempResults = new uint256[](totalApplications);
        uint256 count = 0;

        for (uint256 i = 1; i <= totalApplications; i++) {
            if (applications[i].status == _status) {
                tempResults[count] = i;
                count++;
            }
        }

        // Create array with exact size
        uint256[] memory results = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            results[i] = tempResults[i];
        }

        return results;
    }

    /**
     * @dev Get total number of applications
     * @return Total application count
     */
    function getTotalApplications() external view returns (uint256) {
        return _applicationIds.current();
    }

    /**
     * @dev Check if user is registered
     * @param _user Address to check
     * @return Boolean indicating registration status
     */
    function isUserRegistered(address _user) external view returns (bool) {
        return registeredUsers[_user];
    }

    /**
     * @dev Get user type
     * @param _user Address to check
     * @return UserType of the user
     */
    function getUserType(address _user) external view returns (UserType) {
        require(registeredUsers[_user], "User not registered");
        return userTypes[_user];
    }

    /**
     * @dev Grant government role to an address (admin only)
     * @param _account Address to grant role to
     */
    function grantGovernmentRole(address _account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        grantRole(GOVERNMENT_ROLE, _account);
    }

    /**
     * @dev Grant verifier role to an address (admin only)
     * @param _account Address to grant role to
     */
    function grantVerifierRole(address _account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        grantRole(VERIFIER_ROLE, _account);
    }
}

contracts/CarbonCreditToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title CarbonCreditToken
 * @dev ERC-20 token representing blue carbon credits
 */
contract CarbonCreditToken is ERC20, ERC20Burnable, AccessControl, ReentrancyGuard {
    using Counters for Counters.Counter;

    // Roles
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant GOVERNMENT_ROLE = keccak256("GOVERNMENT_ROLE");
    bytes32 public constant PROJECT_ROLE = keccak256("PROJECT_ROLE");

    // Token metadata
    string private _tokenName = "Blue Carbon Credit";
    string private _tokenSymbol = "BCC";
    uint8 private _tokenDecimals = 18;

    // Credit tracking structures
    struct CreditBatch {
        uint256 batchId;
        address projectContract;
        uint256 amount;
        uint256 mintTimestamp;
        string projectName;
        string landCoordinates;
        uint256 ndviReadingId;
        bool retired;
    }

    struct RetirementRecord {
        uint256 batchId;
        address retiredBy;
        uint256 amount;
        uint256 retirementTimestamp;
        string retirementReason;
    }

    // State variables
    Counters.Counter private _batchIds;
    Counters.Counter private _retirementIds;

    mapping(uint256 => CreditBatch) public creditBatches;
    mapping(address => uint256[]) public userBatches;
    mapping(uint256 => RetirementRecord) public retirements;
    mapping(address => uint256) public totalMintedByProject;
    mapping(address => uint256) public totalRetiredByUser;

    uint256 public totalSupplyMinted;
    uint256 public totalSupplyRetired;

    // Events
    event CreditsMinted(
        uint256 indexed batchId,
        address indexed projectContract,
        address indexed recipient,
        uint256 amount,
        string projectName
    );

    event CreditsRetired(
        uint256 indexed retirementId,
        uint256 indexed batchId,
        address indexed retiredBy,
        uint256 amount,
        string reason
    );

    event ProjectAuthorized(
        address indexed projectContract,
        address indexed authorizer
    );

    event ProjectDeauthorized(
        address indexed projectContract,
        address indexed deauthorizer
    );

    // Modifiers
    modifier onlyAuthorizedMinter() {
        require(
            hasRole(MINTER_ROLE, msg.sender) || 
            hasRole(PROJECT_ROLE, msg.sender) || 
            hasRole(GOVERNMENT_ROLE, msg.sender),
            "Caller is not authorized to mint"
        );
        _;
    }

    modifier validBatchId(uint256 _batchId) {
        require(_batchId > 0 && _batchId <= _batchIds.current(), "Invalid batch ID");
        _;
    }

    constructor(address _governmentAddress) ERC20(_tokenName, _tokenSymbol) {
        require(_governmentAddress != address(0), "Invalid government address");
        
        _grantRole(DEFAULT_ADMIN_ROLE, _governmentAddress);
        _grantRole(GOVERNMENT_ROLE, _governmentAddress);
        _grantRole(MINTER_ROLE, _governmentAddress);
    }

    /**
     * @dev Mint carbon credits for a specific project
     * @param _projectContract Address of the project contract
     * @param _recipient Address to receive the credits
     * @param _amount Amount of credits to mint
     * @param _projectName Name of the project
     * @param _landCoordinates Land coordinates of the project
     * @param _ndviReadingId ID of the NDVI reading that triggered minting
     */
    function mintCredits(
        address _projectContract,
        address _recipient,
        uint256 _amount,
        string memory _projectName,
        string memory _landCoordinates,
        uint256 _ndviReadingId
    ) external onlyAuthorizedMinter nonReentrant {
        require(_projectContract != address(0), "Invalid project contract");
        require(_recipient != address(0), "Invalid recipient address");
        require(_amount > 0, "Amount must be greater than 0");
        require(bytes(_projectName).length > 0, "Project name required");

        // Create new batch
        _batchIds.increment();
        uint256 newBatchId = _batchIds.current();

        CreditBatch storage newBatch = creditBatches[newBatchId];
        newBatch.batchId = newBatchId;
        newBatch.projectContract = _projectContract;
        newBatch.amount = _amount;
        newBatch.mintTimestamp = block.timestamp;
        newBatch.projectName = _projectName;
        newBatch.landCoordinates = _landCoordinates;
        newBatch.ndviReadingId = _ndviReadingId;
        newBatch.retired = false;

        // Update tracking
        userBatches[_recipient].push(newBatchId);
        totalMintedByProject[_projectContract] += _amount;
        totalSupplyMinted += _amount;

        // Mint tokens
        _mint(_recipient, _amount);

        emit CreditsMinted(newBatchId, _projectContract, _recipient, _amount, _projectName);
    }

    /**
     * @dev Retire carbon credits (burn tokens)
     * @param _batchId ID of the credit batch to retire
     * @param _amount Amount of credits to retire
     * @param _reason Reason for retirement
     */
    function retireCredits(
        uint256 _batchId,
        uint256 _amount,
        string memory _reason
    ) external validBatchId(_batchId) nonReentrant {
        require(_amount > 0, "Amount must be greater than 0");
        require(balanceOf(msg.sender) >= _amount, "Insufficient balance");
        require(!creditBatches[_batchId].retired, "Batch already retired");
        require(bytes(_reason).length > 0, "Retirement reason required");

        // Create retirement record
        _retirementIds.increment();
        uint256 newRetirementId = _retirementIds.current();

        RetirementRecord storage newRetirement = retirements[newRetirementId];
        newRetirement.batchId = _batchId;
        newRetirement.retiredBy = msg.sender;
        newRetirement.amount = _amount;
        newRetirement.retirementTimestamp = block.timestamp;
        newRetirement.retirementReason = _reason;

        // Update tracking
        totalRetiredByUser[msg.sender] += _amount;
        totalSupplyRetired += _amount;

        // Mark batch as retired if fully retired
        if (_amount == creditBatches[_batchId].amount) {
            creditBatches[_batchId].retired = true;
        }

        // Burn tokens
        _burn(msg.sender, _amount);

        emit CreditsRetired(newRetirementId, _batchId, msg.sender, _amount, _reason);
    }

    /**
     * @dev Authorize a project contract to mint credits
     * @param _projectContract Address of the project contract
     */
    function authorizeProject(address _projectContract) 
        external 
        onlyRole(GOVERNMENT_ROLE) 
    {
        require(_projectContract != address(0), "Invalid project contract");
        grantRole(PROJECT_ROLE, _projectContract);
        emit ProjectAuthorized(_projectContract, msg.sender);
    }

    /**
     * @dev Deauthorize a project contract
     * @param _projectContract Address of the project contract
     */
    function deauthorizeProject(address _projectContract) 
        external 
        onlyRole(GOVERNMENT_ROLE) 
    {
        revokeRole(PROJECT_ROLE, _projectContract);
        emit ProjectDeauthorized(_projectContract, msg.sender);
    }

    /**
     * @dev Get credit batch information
     * @param _batchId ID of the batch
     * @return CreditBatch struct
     */
    function getCreditBatch(uint256 _batchId) 
        external 
        view 
        validBatchId(_batchId) 
        returns (CreditBatch memory) 
    {
        return creditBatches[_batchId];
    }

    /**
     * @dev Get user's credit batches
     * @param _user Address of the user
     * @return Array of batch IDs
     */
    function getUserBatches(address _user) external view returns (uint256[] memory) {
        return userBatches[_user];
    }

    /**
     * @dev Get retirement record
     * @param _retirementId ID of the retirement
     * @return RetirementRecord struct
     */
    function getRetirementRecord(uint256 _retirementId) 
        external 
        view 
        returns (RetirementRecord memory) 
    {
        require(_retirementId > 0 && _retirementId <= _retirementIds.current(), "Invalid retirement ID");
        return retirements[_retirementId];
    }

    /**
     * @dev Get total number of credit batches
     * @return Total batch count
     */
    function getTotalBatches() external view returns (uint256) {
        return _batchIds.current();
    }

    /**
     * @dev Get total number of retirements
     * @return Total retirement count
     */
    function getTotalRetirements() external view returns (uint256) {
        return _retirementIds.current();
    }

    /**
     * @dev Get project statistics
     * @param _projectContract Address of the project contract
     * @return totalMinted Total credits minted by project
     */
    function getProjectStats(address _projectContract) 
        external 
        view 
        returns (uint256 totalMinted) 
    {
        return totalMintedByProject[_projectContract];
    }

    /**
     * @dev Get user statistics
     * @param _user Address of the user
     * @return totalRetired Total credits retired by user
     * @return currentBalance Current token balance
     */
    function getUserStats(address _user) 
        external 
        view 
        returns (uint256 totalRetired, uint256 currentBalance) 
    {
        return (totalRetiredByUser[_user], balanceOf(_user));
    }

    /**
     * @dev Get global token statistics
     * @return totalMinted Total credits ever minted
     * @return totalRetired Total credits ever retired
     * @return currentSupply Current circulating supply
     */
    function getGlobalStats() 
        external 
        view 
        returns (uint256 totalMinted, uint256 totalRetired, uint256 currentSupply) 
    {
        return (totalSupplyMinted, totalSupplyRetired, totalSupply());
    }

    /**
     * @dev Check if an address is an authorized project
     * @param _projectContract Address to check
     * @return Boolean indicating authorization status
     */
    function isAuthorizedProject(address _projectContract) external view returns (bool) {
        return hasRole(PROJECT_ROLE, _projectContract);
    }

    /**
     * @dev Override decimals to return 18 (standard for carbon credits)
     */
    function decimals() public pure override returns (uint8) {
        return 18;
    }

    /**
     * @dev Grant minter role to an address (Government only)
     * @param _account Address to grant role to
     */
    function grantMinterRole(address _account) external onlyRole(GOVERNMENT_ROLE) {
        grantRole(MINTER_ROLE, _account);
    }

    /**
     * @dev Emergency pause function (Government only)
     * Note: This would require implementing Pausable if needed
     */
    function emergencyMint(
        address _recipient,
        uint256 _amount,
        string memory _reason
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_recipient != address(0), "Invalid recipient");
        require(_amount > 0, "Amount must be greater than 0");
        
        _mint(_recipient, _amount);
        
        // Log as emergency batch
        _batchIds.increment();
        uint256 emergencyBatchId = _batchIds.current();
        
        CreditBatch storage emergencyBatch = creditBatches[emergencyBatchId];
        emergencyBatch.batchId = emergencyBatchId;
        emergencyBatch.projectContract = address(0);
        emergencyBatch.amount = _amount;
        emergencyBatch.mintTimestamp = block.timestamp;
        emergencyBatch.projectName = _reason;
        emergencyBatch.landCoordinates = "Emergency Mint";
        emergencyBatch.ndviReadingId = 0;
        emergencyBatch.retired = false;

        totalSupplyMinted += _amount;
    }
}

contracts/ProjectContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title ProjectContract
 * @dev Individual project contract for tracking blue carbon projects
 */
contract ProjectContract is AccessControl, ReentrancyGuard {
    using Counters for Counters.Counter;

    // Roles
    bytes32 public constant GOVERNMENT_ROLE = keccak256("GOVERNMENT_ROLE");
    bytes32 public constant NGO_ROLE = keccak256("NGO_ROLE");
    bytes32 public constant MONITOR_ROLE = keccak256("MONITOR_ROLE");

    // Project status enum
    enum ProjectStatus {
        Initialized,
        Active,
        Monitoring,
        Completed,
        Suspended
    }

    // Project data structure
    struct ProjectData {
        uint256 applicationId;
        string projectName;
        string landCoordinates;
        uint256 areaHectares;
        string plantSpecies;
        address ngoAddress;
        address governmentApprover;
        uint256 createdAt;
        uint256 startDate;
        uint256 expectedCompletionDate;
        ProjectStatus status;
        uint256 targetCarbonCredits;
        uint256 totalCarbonCreditsEarned;
    }

    // NDVI reading structure
    struct NDVIReading {
        uint256 timestamp;
        uint256 ndviValue;
        uint256 vegetationCoverage;
        uint256 carbonCreditsEarned;
        string satelliteImageHash;
        address recorder;
        bool verified;
    }

    // State variables
    ProjectData public projectData;
    Counters.Counter private _ndviReadingIds;
    
    mapping(uint256 => NDVIReading) public ndviReadings;
    mapping(uint256 => bool) public verifiedReadings;

    // Carbon credit calculation parameters
    uint256 public constant NDVI_THRESHOLD = 6000;
    uint256 public constant BASE_CREDIT_RATE = 10;
    uint256 public constant MAX_CREDITS_PER_READING = 1000;

    // Events
    event ProjectInitialized(uint256 indexed applicationId, address indexed ngoAddress, string projectName);
    event NDVIReadingAdded(uint256 indexed readingId, uint256 ndviValue, uint256 carbonCreditsEarned, address indexed recorder);
    event NDVIReadingVerified(uint256 indexed readingId, address indexed verifier);
    event ProjectStatusUpdated(ProjectStatus oldStatus, ProjectStatus newStatus, address indexed updater);
    event CarbonCreditsCalculated(uint256 indexed readingId, uint256 creditsEarned, uint256 totalCredits);

    constructor(
        uint256 _applicationId,
        string memory _projectName,
        string memory _landCoordinates,
        uint256 _areaHectares,
        string memory _plantSpecies,
        address _ngoAddress,
        address _governmentApprover,
        uint256 _targetCarbonCredits
    ) {
        require(_areaHectares > 0, "Area must be greater than 0");
        require(_ngoAddress != address(0), "Invalid NGO address");
        require(_governmentApprover != address(0), "Invalid government address");

        _grantRole(DEFAULT_ADMIN_ROLE, _governmentApprover);
        _grantRole(GOVERNMENT_ROLE, _governmentApprover);
        _grantRole(NGO_ROLE, _ngoAddress);
        _grantRole(MONITOR_ROLE, _governmentApprover);

        projectData = ProjectData({
            applicationId: _applicationId,
            projectName: _projectName,
            landCoordinates: _landCoordinates,
            areaHectares: _areaHectares,
            plantSpecies: _plantSpecies,
            ngoAddress: _ngoAddress,
            governmentApprover: _governmentApprover,
            createdAt: block.timestamp,
            startDate: 0,
            expectedCompletionDate: 0,
            status: ProjectStatus.Initialized,
            targetCarbonCredits: _targetCarbonCredits,
            totalCarbonCreditsEarned: 0
        });

        emit ProjectInitialized(_applicationId, _ngoAddress, _projectName);
    }

    function addNDVIReading(uint256 _ndviValue, uint256 _vegetationCoverage, string memory _satelliteImageHash) 
        external 
        onlyRole(MONITOR_ROLE) 
        nonReentrant 
    {
        require(_ndviValue <= 10000, "NDVI value cannot exceed 1.0");
        require(_vegetationCoverage <= 10000, "Coverage cannot exceed 100%");

        _ndviReadingIds.increment();
        uint256 newReadingId = _ndviReadingIds.current();

        uint256 carbonCredits = calculateCarbonCredits(_ndviValue);

        NDVIReading storage newReading = ndviReadings[newReadingId];
        newReading.timestamp = block.timestamp;
        newReading.ndviValue = _ndviValue;
        newReading.vegetationCoverage = _vegetationCoverage;
        newReading.carbonCreditsEarned = carbonCredits;
        newReading.satelliteImageHash = _satelliteImageHash;
        newReading.recorder = msg.sender;
        newReading.verified = hasRole(GOVERNMENT_ROLE, msg.sender);

        projectData.totalCarbonCreditsEarned += carbonCredits;

        emit NDVIReadingAdded(newReadingId, _ndviValue, carbonCredits, msg.sender);
        emit CarbonCreditsCalculated(newReadingId, carbonCredits, projectData.totalCarbonCreditsEarned);
    }

    function calculateCarbonCredits(uint256 _ndviValue) public view returns (uint256) {
        if (_ndviValue < NDVI_THRESHOLD) {
            return 0;
        }

        uint256 ndviAboveThreshold = _ndviValue - NDVI_THRESHOLD;
        uint256 credits = (ndviAboveThreshold * projectData.areaHectares * BASE_CREDIT_RATE) / 10000;

        return credits > MAX_CREDITS_PER_READING ? MAX_CREDITS_PER_READING : credits;
    }

    function getNDVIReading(uint256 _readingId) external view returns (NDVIReading memory) {
        require(_readingId > 0 && _readingId <= _ndviReadingIds.current(), "Invalid reading ID");
        return ndviReadings[_readingId];
    }

    function getTotalNDVIReadings() external view returns (uint256) {
        return _ndviReadingIds.current();
    }

    function getProjectProgress() external view returns (uint256) {
        if (projectData.targetCarbonCredits == 0) {
            return 0;
        }
        
        uint256 progress = (projectData.totalCarbonCreditsEarned * 10000) / projectData.targetCarbonCredits;
        return progress > 10000 ? 10000 : progress;
    }
}

